//! src/strutil.cpp) calls.

use std::os::raw::{c_char, c_int};

use super::{CalcRsSink, CalcRsStr};
use crate::strutil;

#[no_mangle]
pub unsafe extern "C" fn calc_rs_strutil_trim(s: CalcRsStr, out: CalcRsSink) {
    out.push(strutil::trim(s.bytes()));
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_strutil_split(s: CalcRsStr, sep: c_char, out: CalcRsSink) {
    for field in strutil::split(s.bytes(), sep as u8) {
        out.push(field);
    }
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_strutil_join(
    parts: *const CalcRsStr,
    count: usize,
    sep: CalcRsStr,
    out: CalcRsSink,
) {
    let parts: Vec<&[u8]> = if count == 0 {
        Vec::new()
    } else {
        std::slice::from_raw_parts(parts, count).iter().map(|p| p.bytes()).collect()
    };
    out.push(&strutil::join(&parts, sep.bytes()));
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_strutil_to_lower(s: CalcRsStr, out: CalcRsSink) {
    out.push(&strutil::to_lower(s.bytes()));
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_strutil_starts_with(s: CalcRsStr, prefix: CalcRsStr) -> bool {
    strutil::starts_with(s.bytes(), prefix.bytes())
}

/// Writes the result to `out` and returns the number of replacements.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_strutil_replace_all(
    s: CalcRsStr,
    from: CalcRsStr,
    to: CalcRsStr,
    out: CalcRsSink,
) -> c_int {
    let (result, count) = strutil::replace_all(s.bytes(), from.bytes(), to.bytes());
    out.push(&result);
    c_int::try_from(count).unwrap_or(c_int::MAX)
}

//! Ported from include/calc/strutil.h, src/strutil.cpp (CodeCoreMorph, D-58).
//!
//! Byte-string helpers. A `std::string` holds bytes, not UTF-8, so these work on `[u8]`.

fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\r' | b'\n')
}

/// Removes spaces, tabs, carriage returns and newlines from both ends.
pub fn trim(s: &[u8]) -> &[u8] {
    let start = s.iter().position(|&b| !is_space(b)).unwrap_or(s.len());
    let end = s.iter().rposition(|&b| !is_space(b)).map_or(start, |i| i + 1);
    &s[start..end]
}

/// Splits on every `sep`: `a,,b` gives `a`, ``, `b`, and `` gives one empty field.
pub fn split(s: &[u8], sep: u8) -> Vec<&[u8]> {
    s.split(|&b| b == sep).collect()
}

pub fn join(parts: &[&[u8]], sep: &[u8]) -> Vec<u8> {
    parts.join(sep)
}

/// ASCII letters only; every other byte stays as it is.
pub fn to_lower(s: &[u8]) -> Vec<u8> {
    s.to_ascii_lowercase()
}

pub fn starts_with(s: &[u8], prefix: &[u8]) -> bool {
    s.starts_with(prefix)
}

/// Replaces each occurrence of `from` (not empty), left to right; returns the result and how
/// many there were.
pub fn replace_all(s: &[u8], from: &[u8], to: &[u8]) -> (Vec<u8>, usize) {
    assert!(!from.is_empty(), "replace_all: `from` is empty");
    let mut out = Vec::with_capacity(s.len());
    let mut count = 0;
    let mut rest = s;
    while let Some(at) = rest.windows(from.len()).position(|w| w == from) {
        out.extend_from_slice(&rest[..at]);
        out.extend_from_slice(to);
        rest = &rest[at + from.len()..];
        count += 1;
    }
    out.extend_from_slice(rest);
    (out, count)
}

