//! The C interface of `crate::lexer`, which the C++ façade (include/calc/lexer.h,
//! src/lexer.cpp) calls.

use std::os::raw::c_int;

use super::{CalcRsSink, CalcRsStr};
use crate::lexer::{Lexer, TokenKind};

/// Token kinds, in the order of `calc::Token::Kind`.
pub const CALC_RS_TOKEN_NUMBER: c_int = 0;
pub const CALC_RS_TOKEN_OPERATOR: c_int = 1;
pub const CALC_RS_TOKEN_LPAREN: c_int = 2;
pub const CALC_RS_TOKEN_RPAREN: c_int = 3;
pub const CALC_RS_TOKEN_NAME: c_int = 4;
pub const CALC_RS_TOKEN_END: c_int = 5;
pub const CALC_RS_TOKEN_INVALID: c_int = 6;

fn code(kind: TokenKind) -> c_int {
    match kind {
        TokenKind::Number => CALC_RS_TOKEN_NUMBER,
        TokenKind::Operator => CALC_RS_TOKEN_OPERATOR,
        TokenKind::LParen => CALC_RS_TOKEN_LPAREN,
        TokenKind::RParen => CALC_RS_TOKEN_RPAREN,
        TokenKind::Name => CALC_RS_TOKEN_NAME,
        TokenKind::End => CALC_RS_TOKEN_END,
        TokenKind::Invalid => CALC_RS_TOKEN_INVALID,
    }
}

/// The token at byte `*pos` of `text`: writes its text to `out` and its offset to `*start`,
/// moves `*pos` past it, and returns its kind.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_lexer_next(
    text: CalcRsStr,
    pos: *mut usize,
    start: *mut usize,
    out: CalcRsSink,
) -> c_int {
    let mut lexer = Lexer::at(text.bytes(), *pos);
    let token = lexer.next_token();
    *pos = lexer.position();
    *start = token.pos;
    out.push(&token.text);
    code(token.kind)
}

//! Ported from include/calc/lexer.h, src/lexer.cpp (CodeCoreMorph, D-58).
//!
//! Splits an expression into integers, `+ - * /`, parentheses and names (`[A-Za-z_]+`,
//! lowercased). The input is bytes, as a `std::string` holds them.

use crate::strutil;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TokenKind {
    Number,
    Operator,
    LParen,
    RParen,
    Name,
    End,
    Invalid,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Token {
    pub kind: TokenKind,
    pub text: Vec<u8>,
    /// The byte offset in the input.
    pub pos: usize,
}

#[derive(Clone, Copy, Debug)]
pub struct Lexer<'a> {
    text: &'a [u8],
    pos: usize,
}

fn is_name_char(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_'
}

impl<'a> Lexer<'a> {
    pub fn new(text: &'a [u8]) -> Self {
        Lexer::at(text, 0)
    }

    /// A lexer that goes on from byte `pos` of `text`.
    pub fn at(text: &'a [u8], pos: usize) -> Self {
        Lexer { text, pos }
    }

    pub fn position(&self) -> usize {
        self.pos
    }

    /// The next token: `End` at the end of the input, and `End` again after that. Any other
    /// character is an `Invalid` token of its own.
    pub fn next_token(&mut self) -> Token {
        self.skip_while(|b| b == b' ' || b == b'\t');
        let start = self.pos;
        let Some(&c) = self.text.get(start) else {
            return Token { kind: TokenKind::End, text: Vec::new(), pos: start };
        };
        let (kind, text) = if c.is_ascii_digit() {
            self.skip_while(|b| b.is_ascii_digit());
            (TokenKind::Number, self.text[start..self.pos].to_vec())
        } else if is_name_char(c) {
            self.skip_while(is_name_char);
            (TokenKind::Name, strutil::to_lower(&self.text[start..self.pos]))
        } else {
            self.pos += 1;
            let kind = match c {
                b'+' | b'-' | b'*' | b'/' => TokenKind::Operator,
                b'(' => TokenKind::LParen,
                b')' => TokenKind::RParen,
                _ => TokenKind::Invalid,
            };
            (kind, vec![c])
        };
        Token { kind, text, pos: start }
    }

    /// The next token, without consuming it.
    pub fn peek(&self) -> Token {
        let mut ahead = *self;
        ahead.next_token()
    }

    fn skip_while(&mut self, wanted: impl Fn(u8) -> bool) {
        while self.pos < self.text.len() && wanted(self.text[self.pos]) {
            self.pos += 1;
        }
    }
}

