// C++ glue of the calc_rs crate for calc::Rational, which the façades share (CodeCoreMorph
// port). C++98.
#ifndef CALC_RS_RATIONAL_HPP
#define CALC_RS_RATIONAL_HPP

#include "calc/rational.h"
#include "calc_rs/bridge.h"

namespace calc_rs {

// A Rational's parts, for Rust.
inline CalcRsRational parts(const calc::Rational& r)
{
    CalcRsRational p;
    p.num = r.num();
    p.den = r.den();
    return p;
}

// The Rational Rust computed (its parts are already in lowest terms).
inline calc::Rational rational(const CalcRsRational& p)
{
    return calc::Rational(p.num, p.den);
}

} // namespace calc_rs

#endif

