//! The C interface of `crate::rational`, which the C++ façade (include/calc/rational.h,
//! src/rational.cpp) calls.

use std::cmp::Ordering;
use std::os::raw::{c_int, c_long};

use super::{CalcRsSink, CalcRsStr};
use crate::rational::{Rational, RationalError};

pub const CALC_RS_OK: c_int = 0;
pub const CALC_RS_ZERO_DENOMINATOR: c_int = 1;
pub const CALC_RS_DIVISION_BY_ZERO: c_int = 2;

/// A `calc::Rational`'s parts, always in lowest terms with a positive denominator.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct CalcRsRational {
    pub num: c_long,
    pub den: c_long,
}

impl From<CalcRsRational> for Rational {
    fn from(r: CalcRsRational) -> Rational {
        Rational::from_normalized(r.num, r.den)
    }
}

impl From<Rational> for CalcRsRational {
    fn from(r: Rational) -> CalcRsRational {
        CalcRsRational { num: r.num(), den: r.den() }
    }
}

fn status(error: RationalError) -> c_int {
    match error {
        RationalError::ZeroDenominator => CALC_RS_ZERO_DENOMINATOR,
        RationalError::DivisionByZero => CALC_RS_DIVISION_BY_ZERO,
    }
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_rational_new(
    num: c_long,
    den: c_long,
    out: *mut CalcRsRational,
) -> c_int {
    match Rational::new(num, den) {
        Ok(r) => {
            *out = r.into();
            CALC_RS_OK
        }
        Err(e) => status(e),
    }
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_add(a: CalcRsRational, b: CalcRsRational) -> CalcRsRational {
    (Rational::from(a) + Rational::from(b)).into()
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_sub(a: CalcRsRational, b: CalcRsRational) -> CalcRsRational {
    (Rational::from(a) - Rational::from(b)).into()
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_mul(a: CalcRsRational, b: CalcRsRational) -> CalcRsRational {
    (Rational::from(a) * Rational::from(b)).into()
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_rational_div(
    a: CalcRsRational,
    b: CalcRsRational,
    out: *mut CalcRsRational,
) -> c_int {
    match Rational::from(a).checked_div(Rational::from(b)) {
        Ok(r) => {
            *out = r.into();
            CALC_RS_OK
        }
        Err(e) => status(e),
    }
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_neg(a: CalcRsRational) -> CalcRsRational {
    (-Rational::from(a)).into()
}

/// -1, 0 or 1.
#[no_mangle]
pub extern "C" fn calc_rs_rational_cmp(a: CalcRsRational, b: CalcRsRational) -> c_int {
    match Rational::from(a).cmp(&Rational::from(b)) {
        Ordering::Less => -1,
        Ordering::Equal => 0,
        Ordering::Greater => 1,
    }
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_truncate(a: CalcRsRational) -> c_long {
    Rational::from(a).truncate()
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_to_double(a: CalcRsRational) -> f64 {
    Rational::from(a).to_f64()
}

#[no_mangle]
pub extern "C" fn calc_rs_rational_str(a: CalcRsRational, out: CalcRsSink) {
    out.push(Rational::from(a).to_string().as_bytes());
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_rational_parse(text: CalcRsStr, out: *mut CalcRsRational) -> bool {
    match Rational::parse(text.bytes()) {
        Some(r) => {
            *out = r.into();
            true
        }
        None => false,
    }
}

//! Ported from include/calc/rational.h, src/rational.cpp (CodeCoreMorph, D-58).
//!
//! A fraction in lowest terms with a positive denominator. The parts are `c_long`, as the C++
//! `long` was: 32 bits on Windows, 64 elsewhere.

use std::cmp::Ordering;
use std::fmt;
use std::ops::{Add, Mul, Neg, Sub};
use std::os::raw::c_long;

use crate::strutil;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rational {
    num: c_long,
    den: c_long,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RationalError {
    ZeroDenominator,
    DivisionByZero,
}

impl fmt::Display for RationalError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            RationalError::ZeroDenominator => "zero denominator",
            RationalError::DivisionByZero => "division by zero",
        })
    }
}

impl std::error::Error for RationalError {}

fn gcd(a: c_long, b: c_long) -> c_long {
    let (mut a, mut b) = (a.abs(), b.abs());
    while b != 0 {
        (a, b) = (b, a % b);
    }
    a
}

/// Reads an optional sign and decimal digits, saturating like `strtol` when out of range.
fn parse_long(text: &[u8]) -> Option<c_long> {
    let (negative, digits) = match text.split_first() {
        Some((b'-', rest)) => (true, rest),
        Some((b'+', rest)) => (false, rest),
        _ => (false, text),
    };
    if digits.is_empty() || !digits.iter().all(u8::is_ascii_digit) {
        return None;
    }
    Some(digits.iter().fold(0 as c_long, |value, &d| {
        let d = c_long::from(d - b'0');
        if negative {
            value.saturating_mul(10).saturating_sub(d)
        } else {
            value.saturating_mul(10).saturating_add(d)
        }
    }))
}

impl Default for Rational {
    fn default() -> Self {
        Rational { num: 0, den: 1 }
    }
}

impl Rational {
    pub fn new(num: c_long, den: c_long) -> Result<Self, RationalError> {
        if den == 0 {
            return Err(RationalError::ZeroDenominator);
        }
        Ok(Self::normalized(num, den))
    }

    pub fn from_integer(n: c_long) -> Self {
        Rational { num: n, den: 1 }
    }

    /// Parts already in lowest terms with a positive denominator, as a `Rational` keeps them.
    pub(crate) fn from_normalized(num: c_long, den: c_long) -> Self {
        debug_assert!(den > 0 && gcd(num, den) <= 1);
        Rational { num, den }
    }

    fn normalized(mut num: c_long, mut den: c_long) -> Self {
        if den < 0 {
            num = -num;
            den = -den;
        }
        let g = gcd(num, den);
        if g > 1 {
            num /= g;
            den /= g;
        }
        Rational { num, den }
    }

    pub fn num(self) -> c_long {
        self.num
    }

    pub fn den(self) -> c_long {
        self.den
    }

    pub fn is_integer(self) -> bool {
        self.den == 1
    }

    /// Rounds toward zero.
    pub fn truncate(self) -> c_long {
        self.num / self.den
    }

    pub fn to_f64(self) -> f64 {
        self.num as f64 / self.den as f64
    }

    pub fn checked_div(self, other: Rational) -> Result<Self, RationalError> {
        if other.num == 0 {
            return Err(RationalError::DivisionByZero);
        }
        Ok(Self::normalized(self.num * other.den, self.den * other.num))
    }

    /// Reads `3`, `-7/2` or ` 1 / 4 `.
    pub fn parse(text: &[u8]) -> Option<Self> {
        let parts = strutil::split(text, b'/');
        if parts.len() > 2 {
            return None;
        }
        let mut values: [c_long; 2] = [0, 1];
        for (value, part) in values.iter_mut().zip(&parts) {
            *value = parse_long(strutil::trim(part))?;
        }
        Rational::new(values[0], values[1]).ok()
    }
}

impl Add for Rational {
    type Output = Rational;
    fn add(self, other: Rational) -> Rational {
        Rational::normalized(self.num * other.den + other.num * self.den, self.den * other.den)
    }
}

impl Sub for Rational {
    type Output = Rational;
    fn sub(self, other: Rational) -> Rational {
        Rational::normalized(self.num * other.den - other.num * self.den, self.den * other.den)
    }
}

impl Mul for Rational {
    type Output = Rational;
    fn mul(self, other: Rational) -> Rational {
        Rational::normalized(self.num * other.num, self.den * other.den)
    }
}

impl Neg for Rational {
    type Output = Rational;
    fn neg(self) -> Rational {
        Rational { num: -self.num, den: self.den }
    }
}

impl PartialOrd for Rational {
    fn partial_cmp(&self, other: &Rational) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Rational {
    fn cmp(&self, other: &Rational) -> Ordering {
        (self.num * other.den).cmp(&(other.num * self.den))
    }
}

impl fmt::Display for Rational {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.den == 1 {
            write!(f, "{}", self.num)
        } else {
            write!(f, "{}/{}", self.num, self.den)
        }
    }
}

