//! The C interface of `crate::expr`, which the C++ façade (include/calc/expr.h,
//! src/expr.cpp) calls. A `CalcRsExpr` is a node Rust owns. A C++ object (any `calc::Expr`,
//! subclasses C++ code defines included) becomes one with its function table, and Rust calls
//! it back.

use std::any::Any;
use std::ffi::c_void;
use std::os::raw::{c_char, c_int};
use std::ptr;

use super::rational::{CalcRsRational, CALC_RS_DIVISION_BY_ZERO, CALC_RS_OK};
use super::CalcRsSink;
use crate::expr::{Binary, Expr, ExprError, Negate, Number};
use crate::rational::Rational;

pub const CALC_RS_UNKNOWN_OPERATOR: c_int = 3;
pub const CALC_RS_EXPR_FAILED: c_int = 4;

/// Node kinds, for C++ to make the object of the right class.
pub const CALC_RS_EXPR_NUMBER: c_int = 0;
pub const CALC_RS_EXPR_NEGATE: c_int = 1;
pub const CALC_RS_EXPR_BINARY: c_int = 2;
pub const CALC_RS_EXPR_FOREIGN: c_int = 3;

/// A node Rust owns, opaque to C.
pub struct CalcRsExpr(Box<dyn Expr>);

/// What Rust calls on a C++ `calc::Expr` it owns. `eval` returns `CALC_RS_OK`,
/// `CALC_RS_DIVISION_BY_ZERO` or `CALC_RS_EXPR_FAILED`, and never throws; `clone` returns a
/// new object; `destroy` deletes the object.
#[repr(C)]
pub struct CalcRsExprVtable {
    pub eval: extern "C" fn(object: *const c_void, out: *mut CalcRsRational) -> c_int,
    pub str: extern "C" fn(object: *const c_void, out: CalcRsSink),
    pub size: extern "C" fn(object: *const c_void) -> c_int,
    pub clone: extern "C" fn(object: *const c_void) -> *mut c_void,
    pub destroy: extern "C" fn(object: *mut c_void),
}

/// A C++ object in a Rust tree. The table outlives it (C++ keeps it static).
struct Foreign {
    object: *mut c_void,
    calls: *const CalcRsExprVtable,
}

impl Foreign {
    fn calls(&self) -> &CalcRsExprVtable {
        // Safety: the table C++ passed is static.
        unsafe { &*self.calls }
    }
}

extern "C" fn push_bytes(ctx: *mut c_void, data: *const u8, len: usize) {
    // Safety: `ctx` is the Vec of `Foreign::text`, alive during the call; `data` holds `len`
    // bytes.
    let out = unsafe { &mut *ctx.cast::<Vec<u8>>() };
    if len > 0 {
        out.extend_from_slice(unsafe { std::slice::from_raw_parts(data, len) });
    }
}

impl Expr for Foreign {
    fn eval(&self) -> Result<Rational, ExprError> {
        let mut out = CalcRsRational { num: 0, den: 1 };
        match (self.calls().eval)(self.object, &mut out) {
            CALC_RS_OK => Ok(Rational::from(out)),
            CALC_RS_DIVISION_BY_ZERO => Err(ExprError::DivisionByZero),
            _ => Err(ExprError::Failed),
        }
    }

    fn text(&self) -> Vec<u8> {
        let mut text: Vec<u8> = Vec::new();
        let sink = CalcRsSink { ctx: ptr::addr_of_mut!(text).cast(), push: push_bytes };
        (self.calls().str)(self.object, sink);
        text
    }

    fn size(&self) -> i32 {
        (self.calls().size)(self.object)
    }

    fn clone_box(&self) -> Box<dyn Expr> {
        Box::new(Foreign { object: (self.calls().clone)(self.object), calls: self.calls })
    }
}

impl Drop for Foreign {
    fn drop(&mut self) {
        if !self.object.is_null() {
            (self.calls().destroy)(self.object);
        }
    }
}

pub(super) fn into_node(expr: Box<dyn Expr>) -> *mut CalcRsExpr {
    Box::into_raw(Box::new(CalcRsExpr(expr)))
}

unsafe fn take(node: *mut CalcRsExpr) -> Box<dyn Expr> {
    Box::from_raw(node).0
}

fn status(error: ExprError) -> c_int {
    match error {
        ExprError::DivisionByZero => CALC_RS_DIVISION_BY_ZERO,
        ExprError::Failed => CALC_RS_EXPR_FAILED,
    }
}

#[no_mangle]
pub extern "C" fn calc_rs_expr_number(value: CalcRsRational) -> *mut CalcRsExpr {
    into_node(Box::new(Number::new(Rational::from(value))))
}

/// A node that takes over `object`, a C++ `calc::Expr`, and calls it through `calls`.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_foreign(
    object: *mut c_void,
    calls: *const CalcRsExprVtable,
) -> *mut CalcRsExpr {
    into_node(Box::new(Foreign { object, calls }))
}

/// A negation that takes over `operand`.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_negate(operand: *mut CalcRsExpr) -> *mut CalcRsExpr {
    into_node(Box::new(Negate::new(take(operand))))
}

/// A binary node in `*out` that takes over `lhs` and `rhs`; `CALC_RS_UNKNOWN_OPERATOR`, with
/// both dropped, when `op` isn't one of `+ - * /`.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_binary(
    op: c_char,
    lhs: *mut CalcRsExpr,
    rhs: *mut CalcRsExpr,
    out: *mut *mut CalcRsExpr,
) -> c_int {
    match Binary::new(op as u8, take(lhs), take(rhs)) {
        Ok(node) => {
            *out = into_node(Box::new(node));
            CALC_RS_OK
        }
        Err(_) => CALC_RS_UNKNOWN_OPERATOR,
    }
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_free(node: *mut CalcRsExpr) {
    if !node.is_null() {
        drop(Box::from_raw(node));
    }
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_eval(
    node: *const CalcRsExpr,
    out: *mut CalcRsRational,
) -> c_int {
    match (*node).0.eval() {
        Ok(value) => {
            *out = value.into();
            CALC_RS_OK
        }
        Err(error) => status(error),
    }
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_str(node: *const CalcRsExpr, out: CalcRsSink) {
    out.push(&(*node).0.text());
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_size(node: *const CalcRsExpr) -> c_int {
    (*node).0.size()
}

#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_clone(node: *const CalcRsExpr) -> *mut CalcRsExpr {
    into_node((*node).0.clone_box())
}

/// The node's kind (`CALC_RS_EXPR_*`), and a binary node's operator in `*op`.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_kind(node: *const CalcRsExpr, op: *mut c_char) -> c_int {
    let any: &dyn Any = &*(*node).0;
    if any.is::<Number>() {
        CALC_RS_EXPR_NUMBER
    } else if any.is::<Negate>() {
        CALC_RS_EXPR_NEGATE
    } else if let Some(binary) = any.downcast_ref::<Binary>() {
        *op = binary.op().symbol() as c_char;
        CALC_RS_EXPR_BINARY
    } else {
        CALC_RS_EXPR_FOREIGN
    }
}

/// The C++ object a foreign node holds, which C++ owns again (the node is freed); null, and the
/// node left as it is, for Rust's own nodes.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_expr_release(node: *mut CalcRsExpr) -> *mut c_void {
    let any: &dyn Any = &*(*node).0;
    if !any.is::<Foreign>() {
        return ptr::null_mut();
    }
    let boxed: Box<dyn Any> = take(node);
    match boxed.downcast::<Foreign>() {
        Ok(mut foreign) => std::mem::replace(&mut foreign.object, ptr::null_mut()),
        Err(_) => ptr::null_mut(),
    }
}

//! Ported from include/calc/expr.h, src/expr.cpp (CodeCoreMorph, D-58).
//!
//! An expression tree. A node owns its children. `Expr` is the interface of the C++ base
//! class: the nodes here implement it, and so do C++ subclasses, which the bridge wraps.

use std::any::Any;
use std::fmt;

use crate::rational::{Rational, RationalError};

/// Why an expression has no value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExprError {
    DivisionByZero,
    /// A node implemented in C++ failed in another way (it threw something else).
    Failed,
}

impl fmt::Display for ExprError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            ExprError::DivisionByZero => "division by zero",
            ExprError::Failed => "an expression failed",
        })
    }
}

impl std::error::Error for ExprError {}

impl From<RationalError> for ExprError {
    fn from(_: RationalError) -> ExprError {
        // Arithmetic on values in lowest terms fails only by dividing by zero.
        ExprError::DivisionByZero
    }
}

/// A node of the tree. `Any` tells callers which kind of node they have.
pub trait Expr: Any {
    fn eval(&self) -> Result<Rational, ExprError>;
    /// Fully parenthesized: `((1/2 + 3) * (-2))`.
    fn text(&self) -> Vec<u8>;
    /// The number of nodes in the tree, this one included.
    fn size(&self) -> i32 {
        1
    }
    /// A deep copy.
    fn clone_box(&self) -> Box<dyn Expr>;
}

#[derive(Clone, Copy, Debug)]
pub struct Number {
    value: Rational,
}

impl Number {
    pub fn new(value: Rational) -> Self {
        Number { value }
    }
}

impl Expr for Number {
    fn eval(&self) -> Result<Rational, ExprError> {
        Ok(self.value)
    }

    fn text(&self) -> Vec<u8> {
        self.value.to_string().into_bytes()
    }

    fn clone_box(&self) -> Box<dyn Expr> {
        Box::new(*self)
    }
}

pub struct Negate {
    operand: Box<dyn Expr>,
}

impl Negate {
    pub fn new(operand: Box<dyn Expr>) -> Self {
        Negate { operand }
    }
}

impl Expr for Negate {
    fn eval(&self) -> Result<Rational, ExprError> {
        Ok(-self.operand.eval()?)
    }

    fn text(&self) -> Vec<u8> {
        [&b"(-"[..], &self.operand.text(), b")"].concat()
    }

    fn size(&self) -> i32 {
        1 + self.operand.size()
    }

    fn clone_box(&self) -> Box<dyn Expr> {
        Box::new(Negate::new(self.operand.clone_box()))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    Add,
    Sub,
    Mul,
    Div,
}

impl Op {
    /// `+ - * /`, or None.
    pub fn from_symbol(symbol: u8) -> Option<Op> {
        match symbol {
            b'+' => Some(Op::Add),
            b'-' => Some(Op::Sub),
            b'*' => Some(Op::Mul),
            b'/' => Some(Op::Div),
            _ => None,
        }
    }

    pub fn symbol(self) -> u8 {
        match self {
            Op::Add => b'+',
            Op::Sub => b'-',
            Op::Mul => b'*',
            Op::Div => b'/',
        }
    }
}

/// A `Binary` was given an operator other than `+ - * /`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct UnknownOperator;

impl fmt::Display for UnknownOperator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("unknown operator")
    }
}

impl std::error::Error for UnknownOperator {}

pub struct Binary {
    op: Op,
    lhs: Box<dyn Expr>,
    rhs: Box<dyn Expr>,
}

impl Binary {
    /// Takes `lhs` and `rhs`, and drops them when `op` isn't one of `+ - * /`.
    pub fn new(op: u8, lhs: Box<dyn Expr>, rhs: Box<dyn Expr>) -> Result<Self, UnknownOperator> {
        let op = Op::from_symbol(op).ok_or(UnknownOperator)?;
        Ok(Binary { op, lhs, rhs })
    }

    pub fn op(&self) -> Op {
        self.op
    }
}

impl Expr for Binary {
    fn eval(&self) -> Result<Rational, ExprError> {
        let left = self.lhs.eval()?;
        let right = self.rhs.eval()?;
        Ok(match self.op {
            Op::Add => left + right,
            Op::Sub => left - right,
            Op::Mul => left * right,
            Op::Div => left.checked_div(right)?,
        })
    }

    fn text(&self) -> Vec<u8> {
        let op = [b' ', self.op.symbol(), b' '];
        [&b"("[..], &self.lhs.text(), &op, &self.rhs.text(), b")"].concat()
    }

    fn size(&self) -> i32 {
        1 + self.lhs.size() + self.rhs.size()
    }

    fn clone_box(&self) -> Box<dyn Expr> {
        Box::new(Binary { op: self.op, lhs: self.lhs.clone_box(), rhs: self.rhs.clone_box() })
    }
}

