/// Parses `text`, with `ans` for the name `ans`: the tree in `*out`, or `CALC_RS_PARSE_ERROR`
/// with the message written to `message` and the error's byte offset in `*pos`.
#[no_mangle]
pub unsafe extern "C" fn calc_rs_parser_parse(
    text: CalcRsStr,
    ans: CalcRsRational,
    out: *mut *mut CalcRsExpr,
    message: CalcRsSink,
    pos: *mut usize,
) -> c_int {
    match parser::parse(text.bytes(), Rational::from(ans)) {
        Ok(tree) => {
            *out = into_node(tree);
            CALC_RS_OK
        }
        Err(error) => {
            message.push(error.message().as_bytes());
            *pos = error.pos();
            CALC_RS_PARSE_ERROR
        }
    }
}

