//!
//! Parses `1 + 2 * (3 - ans) / -4`: integers, `+ - * /` with the usual precedence (left to
//! right), unary minus, parentheses, and the name `ans`, which stands for a given value.

use std::fmt;

use crate::expr::{Binary, Expr, Negate, Number};
use crate::lexer::{Lexer, TokenKind};
use crate::rational::Rational;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParseError {
    message: String,
    pos: usize,
}

impl ParseError {
    pub fn new(message: impl Into<String>, pos: usize) -> Self {
        ParseError { message: message.into(), pos }
    }

    pub fn message(&self) -> &str {
        &self.message
    }

    /// The byte offset of the offending token, or the input's length at its end.
    pub fn pos(&self) -> usize {
        self.pos
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

impl std::error::Error for ParseError {}

const UNARY_MINUS: u8 = b'~';

fn precedence(op: u8) -> i32 {
    match op {
        b'+' | b'-' => 1,
        b'*' | b'/' => 2,
        UNARY_MINUS => 3,
        _ => 0,
    }
}

fn apply(operands: &mut Vec<Box<dyn Expr>>, op: u8, pos: usize) -> Result<(), ParseError> {
    let missing = || ParseError::new("missing operand", pos);
    if op == UNARY_MINUS {
        let operand = operands.pop().ok_or_else(missing)?;
        operands.push(Box::new(Negate::new(operand)));
        return Ok(());
    }
    if operands.len() < 2 {
        return Err(missing());
    }
    let rhs = operands.pop().ok_or_else(missing)?;
    let lhs = operands.pop().ok_or_else(missing)?;
    let node = Binary::new(op, lhs, rhs).map_err(|e| ParseError::new(e.to_string(), pos))?;
    operands.push(Box::new(node));
    Ok(())
}

/// Parses `text`, with `ans` for the name `ans`.
pub fn parse(text: &[u8], ans: Rational) -> Result<Box<dyn Expr>, ParseError> {
    let mut lexer = Lexer::new(text);
    let mut operands: Vec<Box<dyn Expr>> = Vec::new();
    let mut operators: Vec<u8> = Vec::new();
    let mut expect_operand = true;
    loop {
        let token = lexer.next_token();
        match (expect_operand, token.kind) {
            (_, TokenKind::End) => break,
            (true, TokenKind::Number) => {
                let value = Rational::parse(&token.text)
                    .ok_or_else(|| ParseError::new("bad number", token.pos))?;
                operands.push(Box::new(Number::new(value)));
                expect_operand = false;
            }
            (true, TokenKind::Name) => {
                if token.text != b"ans" {
                    let name = String::from_utf8_lossy(&token.text);
                    return Err(ParseError::new(format!("unknown name '{name}'"), token.pos));
                }
                operands.push(Box::new(Number::new(ans)));
                expect_operand = false;
            }
            (true, TokenKind::LParen) => operators.push(b'('),
            (true, TokenKind::Operator) if token.text == b"-" => operators.push(UNARY_MINUS),
            (true, _) => return Err(ParseError::new("expected a number", token.pos)),
            (false, TokenKind::Operator) => {
                let op = token.text[0];
                while let Some(&top) = operators.last() {
                    if precedence(top) < precedence(op) {
                        break;
                    }
                    operators.pop();
                    apply(&mut operands, top, token.pos)?;
                }
                operators.push(op);
                expect_operand = true;
            }
            (false, TokenKind::RParen) => loop {
                match operators.pop() {
                    None => return Err(ParseError::new("unbalanced ')'", token.pos)),
                    Some(b'(') => break,
                    Some(op) => apply(&mut operands, op, token.pos)?,
                }
            },
            (false, _) => return Err(ParseError::new("expected an operator", token.pos)),
        }
    }
    if expect_operand {
        return Err(ParseError::new("unexpected end of input", text.len()));
    }
    while let Some(op) = operators.pop() {
        if op == b'(' {
            return Err(ParseError::new("unbalanced '('", text.len()));
        }
        apply(&mut operands, op, text.len())?;
    }
    operands.pop().ok_or_else(|| ParseError::new("missing operand", text.len()))
}

