use crate::calc::{CalcError, Session};

// The values of calc.h's enum calc_status (not exported: the header has them).
const CALC_OK: c_int = 0;
const CALC_SYNTAX_ERROR: c_int = 1;
const CALC_DIVISION_BY_ZERO: c_int = 2;
const CALC_BUFFER_TOO_SMALL: c_int = 3;
const CALC_NO_RESULT: c_int = 4;

/// A session of the C interface, opaque to C.
pub struct calc_session {
    session: Session,
}

#[no_mangle]
pub extern "C" fn calc_open() -> *mut calc_session {
    Box::into_raw(Box::new(calc_session { session: Session::new() }))
}

#[no_mangle]
pub unsafe extern "C" fn calc_close(session: *mut calc_session) {
    if !session.is_null() {
        drop(Box::from_raw(session));
    }
}

/// Evaluates `text` and writes the result (`7/2`) to `out`; on success it becomes `ans`. On
/// `CALC_SYNTAX_ERROR`, `*error_pos` (unless `error_pos` is null) is the error's byte offset.
#[no_mangle]
pub unsafe extern "C" fn calc_eval(
    session: *mut calc_session,
    text: *const c_char,
    out: *mut c_char,
    out_size: usize,
    error_pos: *mut usize,
) -> c_int {
    let session = &mut (*session).session;
    let result = match session.evaluate(CStr::from_ptr(text).to_bytes()) {
        Ok(result) => result,
        Err(CalcError::Syntax(error)) => {
            if !error_pos.is_null() {
                *error_pos = error.pos();
            }
            return CALC_SYNTAX_ERROR;
        }
        Err(CalcError::DivisionByZero) => return CALC_DIVISION_BY_ZERO,
        // calc.h has no status for it, and the parser builds no node that fails so.
        Err(CalcError::Failed) => return CALC_SYNTAX_ERROR,
    };
    let text = result.to_string();
    if text.len() + 1 > out_size {
        return CALC_BUFFER_TOO_SMALL;
    }
    std::ptr::copy_nonoverlapping(text.as_ptr().cast::<c_char>(), out, text.len());
    *out.add(text.len()) = 0;
    session.keep(result);
    CALC_OK
}

