        Session::default()
    }

    /// The last result kept, 0 at first.
    pub fn ans(&self) -> Rational {
        self.history.last().copied().unwrap_or_default()
    }

    /// The value of `text`, which may name `ans`. Nothing is kept yet: `keep` keeps it (the C
    /// interface keeps only a result that fits the caller's buffer).
    pub fn evaluate(&self, text: &[u8]) -> Result<Rational, CalcError> {
        let tree = parser::parse(text, self.ans()).map_err(CalcError::Syntax)?;
        tree.eval().map_err(|error| match error {
            ExprError::DivisionByZero => CalcError::DivisionByZero,
            ExprError::Failed => CalcError::Failed,
        })
    }

    /// Keeps `result`: it becomes `ans`.
    pub fn keep(&mut self, result: Rational) {
        self.history.push(result);
    }

    /// Forgets the last result; false when there is none.
    pub fn undo(&mut self) -> bool {
        self.history.pop().is_some()
    }

    /// The number of results kept.
    pub fn history_size(&self) -> usize {
        self.history.len()
    }
}

