//! Ported from app/main.cpp (CodeCoreMorph, D-60).
//!
//! tinycalc: evaluates each argument, or else each line of standard input, and prints the
//! results. "ans" is the last result; ":undo" forgets it; lines starting with '#' are comments.
#![forbid(unsafe_code)]

use std::io::{self, BufRead};
use std::process::ExitCode;

use calc_rs::calc::{CalcError, Session};
use calc_rs::strutil;

/// The C++ program read each result into a buffer of this many bytes, its terminating NUL
/// included: a longer result was an error and wasn't kept.
const OUT_SIZE: usize = 64;

/// Runs one line: 1 when it failed, 0 otherwise.
fn run_line(session: &mut Session, raw: &[u8]) -> u32 {
    let line = strutil::trim(raw);
    if line.is_empty() || strutil::starts_with(line, b"#") {
        return 0;
    }
    if strutil::to_lower(line) == b":undo" {
        if !session.undo() {
            eprintln!("error: no result");
            return 1;
        }
        return 0;
    }
    match session.evaluate(line) {
        Ok(result) => {
            let text = result.to_string();
            if text.len() >= OUT_SIZE {
                eprintln!("error: buffer too small");
                return 1;
            }
            session.keep(result);
            println!("{text}");
            0
        }
        Err(CalcError::Syntax(error)) => {
            eprintln!("error: syntax error at column {}", error.pos() + 1);
            1
        }
        Err(CalcError::DivisionByZero) => {
            eprintln!("error: division by zero");
            1
        }
        // The C interface reported it as a syntax error at no position.
        Err(CalcError::Failed) => {
            eprintln!("error: syntax error at column 1");
            1
        }
    }
}

fn main() -> ExitCode {
    let mut session = Session::new();
    let mut failures = 0;
    let args: Vec<_> = std::env::args_os().skip(1).collect();
    if !args.is_empty() {
        for arg in &args {
            failures += run_line(&mut session, arg.as_encoded_bytes());
        }
    } else {
        for line in io::stdin().lock().split(b'\n') {
            let Ok(line) = line else { break };
            failures += run_line(&mut session, &line);
        }
    }
    if failures == 0 {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    }
}

