use std::cell::Cell;
use std::os::raw::c_long;
use std::rc::Rc;

use calc_rs::expr::{Binary, Expr, ExprError, Negate, Number, Op, UnknownOperator};
use calc_rs::rational::Rational;

fn int(n: c_long) -> Rational {
    Rational::from_integer(n)
}

fn number(num: c_long, den: c_long) -> Box<dyn Expr> {
    Box::new(Number::new(Rational::new(num, den).expect("a valid fraction")))
}

fn binary(op: u8, lhs: Box<dyn Expr>, rhs: Box<dyn Expr>) -> Binary {
    Binary::new(op, lhs, rhs).expect("a known operator")
}

/// A leaf defined outside the library, counting how often it is evaluated.
struct Counted {
    value: c_long,
    evals: Rc<Cell<i32>>,
}

impl Expr for Counted {
    fn eval(&self) -> Result<Rational, ExprError> {
        self.evals.set(self.evals.get() + 1);
        Ok(int(self.value))
    }

    fn text(&self) -> Vec<u8> {
        b"#".to_vec()
    }

    fn clone_box(&self) -> Box<dyn Expr> {
        Box::new(Counted { value: self.value, evals: Rc::clone(&self.evals) })
    }
}

#[test]
fn evaluates_a_tree() {
    let tree = binary(
        b'*',
        Box::new(binary(b'+', number(1, 2), number(3, 1))),
        Box::new(Negate::new(number(2, 1))),
    );
    assert_eq!(tree.eval(), Ok(int(-7)));
    assert_eq!(tree.text(), b"((1/2 + 3) * (-2))");
    assert_eq!(tree.size(), 6);
    assert_eq!(tree.op(), Op::Mul);
}

#[test]
fn division_by_zero_throws() {
    let tree = binary(b'/', number(1, 1), Box::new(binary(b'-', number(2, 1), number(2, 1))));
    assert_eq!(tree.eval(), Err(ExprError::DivisionByZero));
}

#[test]
fn unknown_operator_throws() {
    assert!(matches!(Binary::new(b'%', number(1, 1), number(2, 1)), Err(UnknownOperator)));
}

#[test]
fn clone_is_deep() {
    let original: Box<dyn Expr> = Box::new(binary(b'-', number(5, 1), number(3, 1)));
    let copy = original.clone_box();
    drop(original);
    assert_eq!(copy.eval(), Ok(int(2)));
    assert_eq!(copy.text(), b"(5 - 3)");
}

#[test]
fn works_through_the_base_class() {
    let exprs: Vec<Box<dyn Expr>> = vec![
        number(4, 1),
        Box::new(Negate::new(number(1, 2))),
        Box::new(binary(b'/', number(1, 1), number(4, 1))),
    ];
    let mut total = Rational::default();
    let mut nodes = 0;
    for expr in &exprs {
        total = total + expr.eval().expect("a value");
        nodes += expr.size();
    }
    assert_eq!(total, Rational::new(15, 4).expect("a valid fraction"));
    assert_eq!(nodes, 6);
}

#[test]
fn subclasses_work_as_children() {
    let evals = Rc::new(Cell::new(0));
    let counted = |value| Box::new(Counted { value, evals: Rc::clone(&evals) });
    let tree = binary(b'+', counted(2), Box::new(Negate::new(counted(5))));
    assert_eq!(tree.eval(), Ok(int(-3)));
    assert_eq!(evals.get(), 2);
    assert_eq!(tree.text(), b"(# + (-#))");
    assert_eq!(tree.size(), 4);
    let copy = tree.clone_box();
    assert_eq!(copy.eval(), Ok(int(-3)));
    assert_eq!(evals.get(), 4);
}

